using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using ResearchAgent;
using System.ComponentModel;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OpenAI key via AI:ApiKey (user-secrets) or the OPENAI_API_KEY env var.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<NoteStore>();
builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research agent. Given a topic, use the web_search tool to find "
    + "relevant information. Use the save_note tool to record key findings as you go. "
    + "Search multiple queries to cover different angles of the topic. "
    + "After gathering enough information, produce a final Markdown summary using your saved notes.");

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly, then provide a summary:\n\n{topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [
            AIFunctionFactory.Create(tools.WebSearch),
            AIFunctionFactory.Create(tools.SaveNote),
            AIFunctionFactory.Create(tools.GetNotes),
        ],
    },
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant)
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

var noteStore = host.Services.GetRequiredService<NoteStore>();
if (noteStore.Notes.Count > 0)
{
    Console.WriteLine("\n--- Saved Research Notes ---");
    for (var i = 0; i < noteStore.Notes.Count; i++)
    {
        Console.WriteLine($"  [{i + 1}] {noteStore.Notes[i]}");
    }
}

Console.WriteLine("\nDone.");

