+using System.ComponentModel;
+using System.Net;
+using System.Text;
+using System.Text.Json;
+
+namespace ResearchAgent;
+
+/// <summary>
+/// Tools exposed to the research agent for web search and note-taking.
+/// </summary>
+public sealed class ResearchTools(NoteStore noteStore)
+{
+    private static readonly HttpClient s_httpClient = new()
+    {
+        Timeout = TimeSpan.FromSeconds(15),
+    };
+
+    /// <summary>
+    /// Searches the web for the given query and returns a list of result
+    /// titles, URLs, and snippets. Uses the DuckDuckGo Lite HTML endpoint
+    /// so no API key is required.
+    /// </summary>
+    [Description("Search the web for a query. Returns titles, URLs, and snippets.")]
+    public async Task<string> WebSearch(
+        [Description("The search query string")] string query)
+    {
+        try
+        {
+            var encoded = WebUtility.UrlEncode(query);
+            var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
+
+            using var request = new HttpRequestMessage(HttpMethod.Get, url);
+            request.Headers.UserAgent.ParseAdd(
+                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
+
+            using var response = await s_httpClient.SendAsync(request);
+            response.EnsureSuccessStatusCode();
+
+            var html = await response.Content.ReadAsStringAsync();
+            var results = ParseDuckDuckGoLite(html);
+
+            if (results.Count == 0)
+            {
+                return $"No results found for: {query}";
+            }
+
+            var sb = new StringBuilder();
+            sb.AppendLine($"Search results for: {query}");
+            sb.AppendLine();
+
+            foreach (var (title, link, snippet) in results.Take(5))
+            {
+                sb.AppendLine($"Title: {title}");
+                sb.AppendLine($"URL: {link}");
+                sb.AppendLine($"Snippet: {snippet}");
+                sb.AppendLine();
+            }
+
+            return sb.ToString();
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed for '{query}': {ex.Message}";
+        }
+    }
+
+    /// <summary>
+    /// Saves a research note for later summarization.
+    /// </summary>
+    [Description("Save a research note. Use this to record key findings from search results.")]
+    public string SaveNote(
+        [Description("The note content to save")] string note)
+    {
+        var count = noteStore.Add(note);
+        return $"Note saved (total notes: {count}).";
+    }
+
+    /// <summary>
+    /// Returns all saved research notes.
+    /// </summary>
+    [Description("Retrieve all saved research notes collected so far.")]
+    public string GetNotes()
+    {
+        var notes = noteStore.Notes;
+
+        if (notes.Count == 0)
+        {
+            return "No notes saved yet.";
+        }
+
+        var sb = new StringBuilder();
+        sb.AppendLine($"Saved notes ({notes.Count}):");
+
+        for (var i = 0; i < notes.Count; i++)
+        {
+            sb.AppendLine($"  [{i + 1}] {notes[i]}");
+        }
+
+        return sb.ToString();
+    }
+
+    private static List<(string Title, string Url, string Snippet)> ParseDuckDuckGoLite(
+        string html)
+    {
+        var results = new List<(string, string, string)>();
+
+        // DuckDuckGo Lite returns results in a table. Each result has an
+        // anchor tag with class "result-link" followed by a snippet in a
+        // <td class="result-snippet"> element.
+        var linkMarker = "class=\"result-link\"";
+        var snippetMarker = "class=\"result-snippet\">";
+        var index = 0;
+
+        while (index < html.Length && results.Count < 10)
+        {
+            var linkPos = html.IndexOf(linkMarker, index, StringComparison.Ordinal);
+            if (linkPos < 0)
+            {
+                break;
+            }
+
+            // Extract URL from href
+            var hrefPos = html.LastIndexOf("href=\"", linkPos, Math.Min(linkPos, 200),
+                StringComparison.Ordinal);
+            var url = "";
+            if (hrefPos >= 0)
+            {
+                var hrefStart = hrefPos + 6;
+                var hrefEnd = html.IndexOf('"', hrefStart);
+                if (hrefEnd > hrefStart)
+                {
+                    url = WebUtility.HtmlDecode(html[hrefStart..hrefEnd]);
+                }
+            }
+
+            // Extract title from link text
+            var closeTag = html.IndexOf('>', linkPos);
+            var endTag = html.IndexOf("</a>", closeTag, StringComparison.Ordinal);
+            var title = closeTag >= 0 && endTag > closeTag
+                ? StripHtml(html[(closeTag + 1)..endTag]).Trim()
+                : "";
+
+            // Extract snippet
+            var snippetPos = html.IndexOf(snippetMarker, endTag >= 0 ? endTag : linkPos,
+                StringComparison.Ordinal);
+            var snippet = "";
+            if (snippetPos >= 0)
+            {
+                var snippetStart = snippetPos + snippetMarker.Length;
+                var snippetEnd = html.IndexOf("</td>", snippetStart,
+                    StringComparison.Ordinal);
+                if (snippetEnd > snippetStart)
+                {
+                    snippet = StripHtml(html[snippetStart..snippetEnd]).Trim();
+                }
+
+                index = snippetEnd >= 0 ? snippetEnd : snippetStart;
+            }
+            else
+            {
+                index = endTag >= 0 ? endTag + 4 : linkPos + linkMarker.Length;
+            }
+
+            if (!string.IsNullOrWhiteSpace(title))
+            {
+                results.Add((title, url, snippet));
+            }
+        }
+
+        return results;
+    }
+
+    private static string StripHtml(string html)
+    {
+        var sb = new StringBuilder(html.Length);
+        var inTag = false;
+
+        foreach (var c in html)
+        {
+            if (c == '<')
+            {
+                inTag = true;
+            }
+            else if (c == '>')
+            {
+                inTag = false;
+            }
+            else if (!inTag)
+            {
+                sb.Append(c);
+            }
+        }
+
+        return WebUtility.HtmlDecode(sb.ToString());
+    }
+}
